using System.Security.Cryptography;
using KiranaHub.ZkSnarks.Circuit;

namespace KiranaHub.ZkSnarks.Prover;

/// <summary>
/// Proving Key containing pre-computed cryptographic setup parameters.
/// </summary>
public sealed record ProvingKey(
    ArithmeticCircuit Circuit,
    FieldElement Alpha,
    FieldElement Beta,
    FieldElement Delta,
    FieldElement Tau,
    FieldElement[] A_Tau,
    FieldElement[] B_Tau,
    FieldElement[] C_Tau,
    FieldElement Z_Tau);

/// <summary>
/// Non-Interactive Zero-Knowledge Proof (\pi) generated by the Prover.
/// Contains blinded polynomial evaluations (A, B, C) and target quotient H.
/// The verifier checks this in O(1) time without learning the private witness.
/// </summary>
public sealed record ZkProof(
    FieldElement ProofA,
    FieldElement ProofB,
    FieldElement ProofC,
    FieldElement ProofH,
    IReadOnlyList<FieldElement> PublicInputs);

/// <summary>
/// Zero-Knowledge SNARK Prover Engine.
/// Generates mathematical proofs from private witnesses with statistical zero knowledge (blinding factors).
/// </summary>
public static class ZkProver
{
    // [KYA KARTA HAI]: Trusted Setup ceremony execute karta hai circuit ke liye.
    // [KYU ZAROORI HAI]: Common Reference String (CRS) generate karna jisme toxic waste parameters evaluate hote hain.
    // [KAISE CHALTA HAI]: Generates random field elements for alpha, beta, delta, and tau.
    // [OUTPUT / SIDE EFFECT]: ProvingKey and VerifyingKey parameters produced.
    // [VARIATIONS TO TRY]: Multi-party computation (MPC) Powers of Tau ceremony.
    public static ProvingKey GenerateSetup(ArithmeticCircuit circuit)
    {
        // Secret random toxic waste parameters (in production, discarded post-ceremony)
        FieldElement alpha = GenerateRandomFieldElement();
        FieldElement beta = GenerateRandomFieldElement();
        FieldElement delta = GenerateRandomFieldElement();
        FieldElement tau = GenerateRandomFieldElement();

        int varCount = circuit.TotalVariables;
        var aTau = new FieldElement[varCount];
        var bTau = new FieldElement[varCount];
        var cTau = new FieldElement[varCount];

        // Evaluate circuit polynomials at secret point tau
        for (int i = 0; i < circuit.Constraints.Count; i++)
        {
            var c = circuit.Constraints[i];
            foreach (var (vIdx, coeff) in c.A.Terms) aTau[vIdx] += coeff * FieldElement.ModPow(tau, i + 1);
            foreach (var (vIdx, coeff) in c.B.Terms) bTau[vIdx] += coeff * FieldElement.ModPow(tau, i + 1);
            foreach (var (vIdx, coeff) in c.C.Terms) cTau[vIdx] += coeff * FieldElement.ModPow(tau, i + 1);
        }

        // Vanishing polynomial Z(tau) = \prod (tau - root_i)
        FieldElement zTau = FieldElement.One;
        for (int i = 0; i < circuit.Constraints.Count; i++)
        {
            zTau *= (tau - new FieldElement(i + 1));
        }

        return new ProvingKey(circuit, alpha, beta, delta, tau, aTau, bTau, cTau, zTau);
    }

    // [KYA KARTA HAI]: Age Verification ke liye complete witness vector synthesize karta hai aur zero-knowledge proof banata hai.
    // [KYU ZAROORI HAI]: Customer ko prove karna hota hai: "Meri age >= 21 hai" bina birth year 2000 reveal kiye.
    // [KAISE CHALTA HAI]: Private inputs evaluate karta hai, bit-decomposition karta hai, circuit check karta hai, aur proof compute karta hai.
    // [OUTPUT / SIDE EFFECT]: ZkProof instance (\pi) containing blinded cryptographic points.
    // [VARIATIONS TO TRY]: Multi-attribute proof (Age >= 21 AND City == "Mumbai").
    public static ZkProof CreateAgeProof(
        ProvingKey pk,
        AgeCircuitWires wires,
        int currentYear,
        int minAgeThreshold,
        int birthYear)
    {
        var circuit = pk.Circuit;
        var witness = new FieldElement[circuit.TotalVariables];

        // 1. One Wire
        witness[ArithmeticCircuit.OneWire] = FieldElement.One;

        // 2. Public Inputs
        witness[wires.CurrentYearWire] = new FieldElement(currentYear);
        witness[wires.MinAgeThresholdWire] = new FieldElement(minAgeThreshold);

        // 3. Private Calculations
        int age = currentYear - birthYear;
        int diff = age - minAgeThreshold;

        witness[wires.BirthYearWire] = new FieldElement(birthYear);
        witness[wires.AgeWire] = new FieldElement(age);
        witness[wires.DiffWire] = new FieldElement(diff);

        // 4. Bit decomposition of diff
        if (diff < 0)
        {
            // Underage! In modular field diff wraps around to near Modulus (2^31 - 1)
            // It cannot fit in 8 bits! We populate lowest 8 bits, which will fail circuit validation!
            long wrappedDiff = new FieldElement(diff).Value;
            for (int i = 0; i < 8; i++)
            {
                witness[wires.DiffBitsWires[i]] = new FieldElement((wrappedDiff >> i) & 1);
            }
        }
        else
        {
            // Valid age! Exactly decompose diff into 8 bits
            for (int i = 0; i < 8; i++)
            {
                long bit = (diff >> i) & 1;
                witness[wires.DiffBitsWires[i]] = new FieldElement(bit);
            }
        }

        // 5. Verify circuit satisfaction
        if (!circuit.IsWitnessValid(witness, out string? failureReason))
        {
            throw new InvalidOperationException($"Cannot generate valid zk-SNARK proof! Circuit constraint violated: {failureReason}");
        }

        // 6. Generate non-interactive cryptographic proof with blinding factors
        return SynthesizeProof(pk, witness);
    }

    // [KYA KARTA HAI]: Synthesizes blinded zk-SNARK proof points (A, B, C, H) using proving key and witness.
    // [KYU ZAROORI HAI]: Statistical zero knowledge ensure karna (random blinding factors r and s).
    // [KAISE CHALTA HAI]: Computes dot products <A, witness>, applies blinding shifts, and computes quotient H.
    // [OUTPUT / SIDE EFFECT]: Cryptographic ZkProof object.
    // [VARIATIONS TO TRY]: Groth16 elliptic curve pairing exponentiations.
    private static ZkProof SynthesizeProof(ProvingKey pk, IReadOnlyList<FieldElement> witness)
    {
        // Cryptographic blinding scalars r and s (ensures zero-knowledge privacy)
        FieldElement r = GenerateRandomFieldElement();
        FieldElement s = GenerateRandomFieldElement();

        FieldElement aVal = pk.Alpha;
        FieldElement bVal = pk.Beta;
        FieldElement cVal = FieldElement.Zero;

        for (int i = 0; i < witness.Count; i++)
        {
            aVal += witness[i] * pk.A_Tau[i];
            bVal += witness[i] * pk.B_Tau[i];
            cVal += witness[i] * pk.C_Tau[i];
        }

        // Blinding transformations: A' = A + r*delta, B' = B + s*delta
        FieldElement blindedA = aVal + (r * pk.Delta);
        FieldElement blindedB = bVal + (s * pk.Delta);
        FieldElement blindedC = cVal + (s * aVal) + (r * bVal) + (r * s * pk.Delta);

        // Quotient polynomial H(tau) = (A * B - C) / Z(tau)
        FieldElement hVal = (blindedA * blindedB - blindedC) / pk.Z_Tau;

        var publicInputs = pk.Circuit.PublicInputs.Select(idx => witness[idx]).ToList();

        return new ZkProof(blindedA, blindedB, blindedC, hVal, publicInputs);
    }

    // [KYA KARTA HAI]: Cryptographically secure random field element generate karta hai.
    // [KYU ZAROORI HAI]: Blinding factors aur setup parameters me zero bias ensure karna.
    // [KAISE CHALTA HAI]: RandomNumberGenerator.GetInt32 modulo prime.
    // [OUTPUT / SIDE EFFECT]: Random FieldElement in [1, Modulus - 1].
    // [VARIATIONS TO TRY]: Hardware TRNG entropy source.
    private static FieldElement GenerateRandomFieldElement()
    {
        uint val = (uint)RandomNumberGenerator.GetInt32(1, (int)(FieldElement.Modulus - 1));
        return new FieldElement(val);
    }
}
